phase1.code:
// ---- Implementing standard library traits ----

use std::fmt;

// ---- Debug trait (for printing with {:?}) ----
#[derive(Debug)]
struct Player {
    name: String,
    health: i32,
    level: i32,
}

// ---- Display trait (for printing with {}) ----
impl fmt::Display for Player {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{} (Lv. {}, HP: {})", self.name, self.level, self.health)
    }
}

// ---- PartialEq trait (for equality) ----
impl PartialEq for Player {
    fn eq(&self, other: &Self) -> bool {
        self.name == other.name && self.level == other.level
    }
}

// ---- Eq trait (required for some collections) ----
impl Eq for Player {}

// ---- PartialOrd trait (for ordering) ----
impl PartialOrd for Player {
    fn partial_cmp(&self, other: &Self) -> Option<std::cmp::Ordering> {
        self.level.partial_cmp(&other.level)
    }
}

// ---- Ord trait (for full ordering) ----
impl Ord for Player {
    fn cmp(&self, other: &Self) -> std::cmp::Ordering {
        self.level.cmp(&other.level)
    }
}

// ---- Clone trait ----
impl Clone for Player {
    fn clone(&self) -> Self {
        Player {
            name: self.name.clone(),
            health: self.health,
            level: self.level,
        }
    }
}

// ---- Default trait ----
impl Default for Player {
    fn default() -> Self {
        Player {
            name: String::from("Unknown"),
            health: 100,
            level: 1,
        }
    }
}

// ---- Custom trait ----
trait Describable {
    fn description(&self) -> String;
}

impl Describable for Player {
    fn description(&self) -> String {
        format!("A level {} player named {}", self.level, self.name)
    }
}

// ---- Custom trait for enemies ----
struct Enemy {
    name: String,
    health: i32,
    is_boss: bool,
}

impl Describable for Enemy {
    fn description(&self) -> String {
        let boss_str = if self.is_boss { "boss " } else { "" };
        format!("A {}enemy named {} with {} HP", boss_str, self.name, self.health)
    }
}

// ---- Trait as parameter ----
fn print_description(item: &impl Describable) {
    println!("{}", item.description());
}

// ---- Trait bound ----
fn print_description_generic<T: Describable>(item: &T) {
    println!("{}", item.description());
}

// ---- Multiple trait bounds ----
fn print_display_and_describable<T: fmt::Display + Describable>(item: &T) {
    println!("Display: {}", item);
    println!("Description: {}", item.description());
}

fn main() {
    // ---- Creating players ----
    let player1 = Player {
        name: String::from("Hero"),
        health: 100,
        level: 5,
    };

    let player2 = Player {
        name: String::from("Aragorn"),
        health: 120,
        level: 8,
    };

    let player3 = Player {
        name: String::from("Hero"),
        health: 80,
        level: 5,
    };

    // ---- Display ----
    println!("Display: {}", player1);
    println!("Debug: {:?}", player1);

    // ---- Equality ----
    println!("player1 == player3: {}", player1 == player3);
    println!("player1 == player2: {}", player1 == player2);

    // ---- Ordering ----
    println!("player1 < player2: {}", player1 < player2);
    println!("player1 > player2: {}", player1 > player2);

    // ---- Clone ----
    let player4 = player1.clone();
    println!("Cloned: {}", player4);

    // ---- Default ----
    let default_player = Player::default();
    println!("Default: {}", default_player);

    // ---- Custom trait ----
    let enemy = Enemy {
        name: String::from("Goblin"),
        health: 30,
        is_boss: false,
    };

    print_description(&player1);
    print_description(&enemy);

    // ---- Generic with trait bound ----
    print_description_generic(&player2);

    // ---- Multiple trait bounds ----
    print_display_and_describable(&player1);
}

